QIcon edgeIcon(const QString& edge){QPixmap pixels(18,18);pixels.fill(Qt::transparent);QPainter p(&pixels);p.setPen(QPen(QColor("#777777"),1,Qt::DotLine));p.drawRect(2,2,13,13);p.drawLine(2,8,15,8);p.drawLine(8,2,8,15);p.setPen(QPen(Qt::black,1));if(edge=="top")p.drawLine(2,2,15,2);else if(edge=="bottom")p.drawLine(2,15,15,15);else if(edge=="left")p.drawLine(2,2,2,15);else if(edge=="right")p.drawLine(15,2,15,15);else if(edge=="middleHorizontal")p.drawLine(2,8,15,8);else if(edge=="middleVertical")p.drawLine(8,2,8,15);else if(edge=="diagonalUp")p.drawLine(2,15,15,2);else p.drawLine(2,2,15,15);return QIcon(pixels);}
class EdgeButton final:public QCheckBox {
public:EdgeButton(const QString& edge,QWidget* parent):QCheckBox(parent){setObjectName("formatCells.border."+edge);setAccessibleName(edge+" border");setIcon(edgeIcon(edge));setFixedSize(22,21);setCursor(Qt::ArrowCursor);setMouseTracking(true);}
protected:bool hitButton(const QPoint& p)const override{return rect().contains(p);}
 void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),isChecked()?QColor("#d9e9f7"):QColor("#f0f0f0"));p.setPen(underMouse()?QColor("#0078d7"):QColor("#aaaaaa"));p.drawRect(rect().adjusted(0,0,-1,-1));icon().paint(&p,QRect(2,1,18,18),Qt::AlignCenter,isEnabled()?QIcon::Normal:QIcon::Disabled);}
};
QIcon presetIcon(const QString& name){QPixmap pixels(30,30);pixels.fill(Qt::transparent);QPainter p(&pixels);p.setPen(QPen(QColor("#555555"),1,Qt::DotLine));p.drawRect(3,3,23,23);p.drawLine(3,14,26,14);p.drawLine(14,3,14,26);p.setPen(QPen(Qt::black,1));if(name=="outline")p.drawRect(3,3,23,23);if(name=="inside"){p.drawLine(3,14,26,14);p.drawLine(14,3,14,26);}return QIcon(pixels);}
