void lineSample(QPainter& p,QRect rect,const QString& name){if(name=="none"){p.setPen(Qt::black);p.drawText(rect,Qt::AlignCenter,"None");return;}QPen pen(Qt::black,name=="thick"?3:name.startsWith("medium")?2:1);if(name=="hair"||name=="dotted")pen.setStyle(Qt::DotLine);else if(name.contains("DashDotDot",Qt::CaseInsensitive)||name=="dashDotDot")pen.setStyle(Qt::DashDotDotLine);else if(name.contains("DashDot",Qt::CaseInsensitive)||name=="dashDot")pen.setStyle(Qt::DashDotLine);else if(name.contains("dash",Qt::CaseInsensitive))pen.setStyle(Qt::DashLine);p.setPen(pen);const int y=rect.center().y();p.drawLine(rect.left()+4,y,rect.right()-4,y);if(name=="double")p.drawLine(rect.left()+4,y+3,rect.right()-4,y+3);}
class LineDelegate final:public QStyledItemDelegate {
public:using QStyledItemDelegate::QStyledItemDelegate;
 void paint(QPainter* p,const QStyleOptionViewItem& option,const QModelIndex& index)const override{p->save();p->fillRect(option.rect,Qt::white);lineSample(*p,option.rect,index.data(Qt::UserRole).toString());if(option.state&QStyle::State_Selected){p->setPen(QPen(QColor("#777777"),1,Qt::DotLine));p->drawRect(option.rect.adjusted(1,1,-2,-2));}p->restore();}
 QSize sizeHint(const QStyleOptionViewItem&,const QModelIndex&)const override{return {59,16};}
};
class BorderPreview final:public QWidget {
public:std::array<QCheckBox*,4> outer{};QCheckBox* horizontal=nullptr;QCheckBox* vertical=nullptr;QCheckBox* up=nullptr;QCheckBox* down=nullptr;WorksheetBorderDraft& draft;int rows,columns;
 BorderPreview(QWidget* parent,WorksheetBorderDraft& value,int r,int c):QWidget(parent),draft(value),rows(r),columns(c){setObjectName("formatCells.borderPreview");setAccessibleName("Border live preview");setFixedSize(151,98);}
protected:void paintEvent(QPaintEvent*)override{QPainter p(this);p.fillRect(rect(),Qt::white);p.setPen(QColor("#8c8c8c"));p.drawRect(rect().adjusted(0,0,-1,-1));const int x=width()-8,y=height()-8,mx=width()/2,my=height()/2;for(const QPoint& corner:{QPoint(7,7),QPoint(x,7),QPoint(7,y),QPoint(x,y)}){const int dx=corner.x()==7?5:-5,dy=corner.y()==7?5:-5;p.drawLine(corner,corner+QPoint(dx,0));p.drawLine(corner,corner+QPoint(0,dy));}if(columns>1){p.drawLine(mx,7,mx,12);p.drawLine(mx-3,12,mx+3,12);p.drawLine(mx,y,mx,y-5);p.drawLine(mx-3,y-5,mx+3,y-5);}if(rows>1){p.drawLine(7,my,12,my);p.drawLine(x,my,x-5,my);}p.setPen(Qt::black);if(rows>1){p.drawText(QRect(9,9,width()-18,height()-18),Qt::AlignCenter,"Text       Text\n\nText       Text");}else p.drawText(QRect(9,9,width()-18,height()-18),Qt::AlignCenter,columns>1?"Text        Text":"Text");QColor color(QString::fromStdString(draft.color));if(!color.isValid())color=Qt::black;const QRect edges(7,7,x-6,y-6);const std::array<const char*,4> sides{"top","bottom","left","right"};for(int i=0;i<4;++i)if(outer[i]&&outer[i]->isChecked())paintWorksheetBorder(p,edges,sides[i],draft.style,color);if(horizontal&&horizontal->isChecked())paintWorksheetBorder(p,QRect(7,my,x-6,y-my+1),"top",draft.style,color);if(vertical&&vertical->isChecked())paintWorksheetBorder(p,QRect(mx,7,x-mx+1,y-6),"left",draft.style,color);if(up&&up->isChecked())paintWorksheetBorder(p,edges,"diagonalUp",draft.style,color);if(down&&down->isChecked())paintWorksheetBorder(p,edges,"diagonalDown",draft.style,color);}
 void mouseReleaseEvent(QMouseEvent* event)override{if(event->button()!=Qt::LeftButton)return;const auto p=event->position().toPoint();if(p.y()<15&&outer[0])outer[0]->click();else if(p.y()>height()-16&&outer[1])outer[1]->click();else if(p.x()<15&&outer[2])outer[2]->click();else if(p.x()>width()-16&&outer[3])outer[3]->click();else if(rows>1&&std::abs(p.y()-height()/2)<8&&horizontal)horizontal->click();else if(columns>1&&std::abs(p.x()-width()/2)<8&&vertical)vertical->click();else{const double dx=width()-15,dy=height()-15,length=std::hypot(dx,dy);const double upward=std::abs((p.x()-7)*dy+(p.y()-(height()-8))*dx)/length;const double downward=std::abs((p.x()-7)*dy-(p.y()-7)*dx)/length;if(upward<7&&upward<=downward&&up)up->click();else if(downward<7&&down)down->click();}}
};
