Json worksheetBorderOperations(const WorksheetBorderDraft& draft,const WorksheetModel& model,const QItemSelectionRange& range){
 Json operations=Json::array();if(!draft.structured())return operations;if(static_cast<std::uint64_t>(range.height())*range.width()>100000)throw std::invalid_argument("Select a rectangular range of at most 100,000 cells to format borders");const QColor color(QString::fromStdString(draft.color));if(draft.style!="none"&&(!color.isValid()||color.alpha()!=255))throw std::invalid_argument("Choose a valid opaque border color");const Json edge=draft.style!="none"?Json{{"style",draft.style},{"color",color.name().toStdString()}}:Json();
 for(int row=range.top();row<=range.bottom();++row)for(int column=range.left();column<=range.right();++column){Json patch=Json::object();auto boundary=[&](const std::string& side){return (side=="top"&&row==range.top())||(side=="bottom"&&row==range.bottom())||(side=="left"&&column==range.left())||(side=="right"&&column==range.right());};if(draft.clearAll)for(const auto* side:{"top","bottom","left","right"})patch[side]=nullptr;for(const auto& [side,value]:draft.changes.items())if(boundary(side))patch[side]=value;for(const auto& side:draft.perimeterEdges)if(boundary(side))patch[side]=edge;
  if(draft.horizontalTouched){if(row>range.top())patch["top"]=draft.horizontal?edge:Json();if(row<range.bottom())patch["bottom"]=draft.horizontal?edge:Json();}if(draft.verticalTouched){if(column>range.left())patch["left"]=draft.vertical?edge:Json();if(column<range.right())patch["right"]=draft.vertical?edge:Json();}if(draft.diagonalUpTouched)patch["diagonalUp"]=draft.diagonalUp?edge:Json();if(draft.diagonalDownTouched)patch["diagonalDown"]=draft.diagonalDown?edge:Json();
  auto border=model.cellStyle(row,column).value("border",Json::object());for(const auto& [side,value]:patch.items())if(value.is_null())border.erase(side);else border[side]=value;if(border.contains("diagonalUp")&&border.contains("diagonalDown")&&((draft.diagonalUpTouched&&draft.diagonalUp)||(draft.diagonalDownTouched&&draft.diagonalDown))){patch["diagonalUp"]=edge;patch["diagonalDown"]=edge;}if(!patch.empty())operations.push_back({{"type","set_style"},{"sheet",model.sheetId().toStdString()},{"row",row+1},{"col",column+1},{"style",{{"border",std::move(patch)}}}});
 }return operations;
}
